def gen(rng):
    LO, HI = -2**31, 2**31 - 1
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{a} {b}' for a, b in ps)
    def nz(lo, hi):
        while True:
            v = rng.randint(lo, hi)
            if v != 0:
                return v
    tests = [
        fmt([(10, 3)]), fmt([(LO, -1)]), fmt([(LO, 1)]), fmt([(HI, 1)]), fmt([(HI, -1)]),
        fmt([(LO, LO), (HI, LO), (LO, HI), (HI, HI), (0, LO), (0, 1)]),
        fmt([(7, -2), (-7, 2), (-7, -2), (7, 2), (1, 2), (-1, 2), (1, -2), (5, 5), (-5, 5), (5, -5), (3, 7)]),
        fmt([(LO + 1, -1), (LO + 1, 1), (LO, 2), (LO, -2), (LO, 3), (HI, 2), (HI, -3), (LO, HI)]),
    ]
    for _ in range(16):
        n = rng.randint(1, 15)
        r = rng.choice([10, 100, 10**6, 2**31 - 1])
        tests.append(fmt([(rng.randint(-r, r), nz(-r, r)) for _ in range(n)]))
    big = []
    for _ in range(20000):
        big.append((rng.randint(2**30, HI) * rng.choice([1, -1]), rng.choice([1, -1, 2, -2, 3, 7, -5])))
    tests.append(fmt(big))
    big = [(rng.randint(LO, HI), nz(-3, 3)) for _ in range(20000)]
    tests.append(fmt(big))
    big = [(rng.randint(LO, HI), rng.randint(LO, HI) or 1) for _ in range(20000)]
    tests.append(fmt(big))
    big = [(HI if rng.random() < 0.5 else LO, 1 if rng.random() < 0.5 else -1) for _ in range(20000)]
    tests.append(fmt(big))
    return tests
